package test.atriasoft.archidata.dataAccess;

import java.io.IOException;
import java.util.UUID;

import org.atriasoft.archidata.annotation.Collection;
import org.atriasoft.archidata.model.UUIDGenericData;
import org.atriasoft.archidata.model.UUIDGenericDataSoftDelete;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import test.atriasoft.archidata.ConfigureDb;

/** The UUID primary key is generated by the insertion (no database-side default value). */
class TestUuidIdGeneration {

	@Collection("UuidIdGen")
	public static class ModelUuid extends UUIDGenericData {
		public String data;
	}

	@Collection("UuidIdGenSoftDelete")
	public static class ModelUuidSoftDelete extends UUIDGenericDataSoftDelete {
		public String data;
	}

	@BeforeAll
	static void setup() throws Exception {
		ConfigureDb.configure();
	}

	@AfterAll
	static void cleanup() throws IOException {
		ConfigureDb.clear();
	}

	@Test
	void testInsertGeneratesUuid() throws Exception {
		final ModelUuid first = new ModelUuid();
		first.data = "first";
		final ModelUuid second = new ModelUuid();
		second.data = "second";
		final ModelUuid insertedFirst = ConfigureDb.da.insert(first);
		final ModelUuid insertedSecond = ConfigureDb.da.insert(second);
		final UUID uuid = insertedFirst.getUuid();
		Assertions.assertNotNull(uuid);
		Assertions.assertNotNull(insertedSecond.getUuid());
		Assertions.assertNotEquals(uuid, insertedSecond.getUuid());
		final ModelUuid read = ConfigureDb.da.getById(ModelUuid.class, uuid);
		Assertions.assertNotNull(read);
		Assertions.assertEquals(uuid, read.getUuid());
		Assertions.assertEquals("first", read.data);
	}

	@Test
	void testSoftDeleteInsertGeneratesUuid() throws Exception {
		final ModelUuidSoftDelete entry = new ModelUuidSoftDelete();
		entry.data = "soft";
		final ModelUuidSoftDelete inserted = ConfigureDb.da.insert(entry);
		Assertions.assertNotNull(inserted.getUuid());
		Assertions.assertEquals(inserted.getUuid(),
				ConfigureDb.da.getById(ModelUuidSoftDelete.class, inserted.getUuid()).getUuid());
	}
}
